CREATE TABLE IF NOT EXISTS promotion_campaign (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT NOT NULL DEFAULT '0',
    campaign_no VARCHAR(128) NOT NULL,
    campaign_code VARCHAR(128),
    display_name VARCHAR(256) NOT NULL,
    description VARCHAR(1024),
    channel_scope VARCHAR(32) NOT NULL DEFAULT 'ALL',
    audience_scope VARCHAR(32) NOT NULL DEFAULT 'ALL',
    starts_at TEXT NOT NULL,
    ends_at TEXT,
    status VARCHAR(32) NOT NULL DEFAULT 'DRAFT',
    version BIGINT NOT NULL DEFAULT 0,
    created_by TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_campaign_no UNIQUE (tenant_id, campaign_no)
);

CREATE INDEX IF NOT EXISTS idx_promotion_campaign_tenant_status
    ON promotion_campaign (tenant_id, organization_id, status, starts_at DESC);

CREATE TABLE IF NOT EXISTS promotion_offer (
    id TEXT PRIMARY KEY,
    uuid VARCHAR(64) NOT NULL UNIQUE,
    tenant_id TEXT NOT NULL,
    organization_id TEXT NOT NULL DEFAULT '0',
    campaign_id TEXT,
    offer_no VARCHAR(128) NOT NULL,
    offer_code VARCHAR(128),
    offer_type VARCHAR(32) NOT NULL,
    audience_scope VARCHAR(32) NOT NULL DEFAULT 'ALL',
    combinability VARCHAR(32) NOT NULL DEFAULT 'EXCLUSIVE',
    priority INTEGER NOT NULL DEFAULT 0,
    goods_scope VARCHAR(32) NOT NULL DEFAULT 'BOTH',
    current_offer_version_id TEXT,
    display_name VARCHAR(256) NOT NULL,
    description VARCHAR(1024),
    starts_at TEXT NOT NULL,
    ends_at TEXT,
    status VARCHAR(32) NOT NULL DEFAULT 'active',
    version BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    CONSTRAINT uk_promotion_offer_no UNIQUE (tenant_id, offer_no)
);

CREATE INDEX IF NOT EXISTS idx_promotion_offer_tenant_status
    ON promotion_offer (tenant_id, organization_id, status, priority DESC, starts_at DESC);
CREATE INDEX IF NOT EXISTS idx_promotion_offer_tenant_type
    ON promotion_offer (tenant_id, offer_type, status);
CREATE INDEX IF NOT EXISTS idx_promotion_offer_campaign
    ON promotion_offer (tenant_id, organization_id, campaign_id, status);

CREATE TABLE IF NOT EXISTS promotion_offer_version (
