-- folded migration: migrations/postgres/0005_enum_normalization_and_benefit_columns.up.sql
-- sdkwork:migration
-- id: 0005_enum_normalization_and_benefit_columns
-- engine: postgres
-- module: promotion
-- purpose: normalize status/type enums to lowercase, materialize coupon benefit columns for SQL querying, add offer soft-delete column
-- reversible: false
-- transactional: true

-- ============ 1. 状态/类型枚举统一小写 ============

-- promotion_campaign.status
UPDATE promotion_campaign SET status = LOWER(status);
ALTER TABLE promotion_campaign ALTER COLUMN status SET DEFAULT 'draft';

-- promotion_code_batch.status
UPDATE promotion_code_batch SET status = LOWER(status);
ALTER TABLE promotion_code_batch ALTER COLUMN status SET DEFAULT 'pending';

-- promotion_distribution_task.status
UPDATE promotion_distribution_task SET status = LOWER(status);
ALTER TABLE promotion_distribution_task ALTER COLUMN status SET DEFAULT 'pending';

-- promotion_coupon_stock.stock_type
UPDATE promotion_coupon_stock SET stock_type = LOWER(stock_type);
ALTER TABLE promotion_coupon_stock DROP CONSTRAINT IF EXISTS chk_promotion_coupon_stock_type;
ALTER TABLE promotion_coupon_stock ADD CONSTRAINT chk_promotion_coupon_stock_type CHECK (stock_type IN ('limited', 'unlimited'));

-- promotion_coupon_stock.code_issue_mode
UPDATE promotion_coupon_stock SET code_issue_mode = LOWER(code_issue_mode);
ALTER TABLE promotion_coupon_stock ALTER COLUMN code_issue_mode SET DEFAULT 'realtime';

-- 历史核销/回滚状态对齐契约枚举
UPDATE promotion_user_coupon SET status = 'redeemed' WHERE status = 'used';
UPDATE promotion_discount_application SET status = 'rolled_back' WHERE status = 'reversed';

-- ============ 2. 权益结构化列（promotion_offer_version） ============

ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_kind VARCHAR(32);
ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_grant_amount TEXT;
ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_bonus_amount TEXT;
ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_grant_points TEXT;
ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_period VARCHAR(16);
ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_duration_days BIGINT;
ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_daily_quota BIGINT;
ALTER TABLE promotion_offer_version ADD COLUMN IF NOT EXISTS benefit_total_quota BIGINT;

-- 存量回填：从 rule_json 提取权益写入结构化列（rule_json 结构 {"couponBenefit":{...}}）
UPDATE promotion_offer_version
SET benefit_kind = LOWER(COALESCE(rule_json::jsonb #>> '{couponBenefit,kind}', rule_json::jsonb #>> '{benefit,kind}')),
    benefit_grant_amount = COALESCE(rule_json::jsonb #>> '{couponBenefit,grantAmount}', rule_json::jsonb #>> '{benefit,grantAmount}'),
    benefit_bonus_amount = COALESCE(rule_json::jsonb #>> '{couponBenefit,bonusAmount}', rule_json::jsonb #>> '{benefit,bonusAmount}'),
    benefit_grant_points = COALESCE(rule_json::jsonb #>> '{couponBenefit,grantPoints}', rule_json::jsonb #>> '{benefit,grantPoints}'),
    benefit_period = COALESCE(rule_json::jsonb #>> '{couponBenefit,period}', rule_json::jsonb #>> '{benefit,period}'),
    benefit_duration_days = COALESCE(
        (rule_json::jsonb #>> '{couponBenefit,durationDays}')::BIGINT,
        (rule_json::jsonb #>> '{benefit,durationDays}')::BIGINT
    ),
    benefit_daily_quota = COALESCE(
        (rule_json::jsonb #>> '{couponBenefit,dailyQuota}')::BIGINT,
        (rule_json::jsonb #>> '{benefit,dailyQuota}')::BIGINT
    ),
    benefit_total_quota = COALESCE(
        (rule_json::jsonb #>> '{couponBenefit,totalQuota}')::BIGINT,
        (rule_json::jsonb #>> '{benefit,totalQuota}')::BIGINT
    )
WHERE rule_json IS NOT NULL AND rule_json <> '';

